<?php
declare(strict_types=1);
final class OwnerCustomerSettingsFailure extends RuntimeException{public function __construct(public int $status,string $message){parent::__construct($message);}}
function ocs_need(bool $ok,string $message,int $status=503):void{if(!$ok)throw new OwnerCustomerSettingsFailure($status,$message);}
function ocs_dir(bool $create=false):string{$dir=__DIR__.'/runtime';ocs_need(!is_link($dir)&&(!file_exists($dir)||is_dir($dir)),'Приватное хранилище настроек недоступно.');if($create&&!is_dir($dir))ocs_need(@mkdir($dir,0700),'Не удалось создать приватное хранилище.');return $dir;}
function ocs_read():array{$path=ocs_dir().'/customer-settings.json';ocs_need(!is_link($path),'Небезопасный путь настроек.');if(!is_file($path))return ['version'=>0,'prep_enabled'=>false,'public_enabled'=>false];ocs_need(filesize($path)<=65536,'Некорректный размер настроек.');$s=json_decode((string)file_get_contents($path),true);ocs_need(is_array($s)&&is_int($s['version']??null),'Настройки повреждены; сохранённые значения не перезаписываются.');return $s;}
function ocs_atomic(string $path,array $value):void{ocs_need(!is_link($path),'Небезопасный путь сохранения.');$tmp=dirname($path).'/'.bin2hex(random_bytes(16)).'.tmp';$h=@fopen($tmp,'x');ocs_need(is_resource($h),'Не удалось сохранить настройки.');try{chmod($tmp,0600);$data=json_encode($value,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR);ocs_need(fwrite($h,$data)===strlen($data)&&fflush($h),'Запись настроек не завершена.');if(function_exists('fsync'))fsync($h);fclose($h);$h=null;ocs_need(rename($tmp,$path),'Не удалось заменить файл настроек.');}finally{if(is_resource($h))fclose($h);if(is_file($tmp))unlink($tmp);}}
function ocs_locked(callable $fn):mixed{$dir=ocs_dir(true);$path=$dir.'/customer-settings.lock';ocs_need(!is_link($path),'Небезопасный файл блокировки.');$h=fopen($path,'c');ocs_need(is_resource($h),'Не удалось открыть настройки.');chmod($path,0600);ocs_need(flock($h,LOCK_EX),'Настройки заняты.');try{return $fn();}finally{flock($h,LOCK_UN);fclose($h);}}
function ocs_save(array &$s,string $action,array $evidence=[]):void{
 $event=bin2hex(random_bytes(16));$parent=$s['audit_tip']??null;$version=$s['version']+1;$path=ocs_dir(true).'/customer-settings-audit.jsonl';ocs_need(!is_link($path),'Небезопасный путь истории.');$h=fopen($path,'c+b');ocs_need(is_resource($h),'История настроек недоступна.');chmod($path,0600);
 try{$size=fstat($h)['size'];if($size>0){fseek($h,-1,SEEK_END);ocs_need(fread($h,1)==="\n",'Журнал настроек требует проверки; изменение не применено.');}fseek($h,0,SEEK_END);$line=json_encode(['event_id'=>$event,'parent_event'=>$parent,'phase'=>'prepared','actor'=>'owner','actor_id'=>1,'version'=>$version,'time'=>gmdate('c'),'action'=>$action,'evidence'=>$evidence],JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR)."\n";ocs_need(fwrite($h,$line)===strlen($line)&&fflush($h),'История настроек не сохранена; изменение не применено.');if(function_exists('fsync'))ocs_need(fsync($h),'История настроек не синхронизирована.');}finally{fclose($h);}
 // Only an atomic state commit makes this prepared event (and its parent chain) active.
 $s['version']=$version;$s['audit_tip']=$event;$s['updated_at']=gmdate('c');ocs_atomic(ocs_dir().'/customer-settings.json',$s);
}
function ocs_policy(string $version):?array{if(!preg_match('/^customer-privacy-[0-9]{8}-[a-f0-9]{16}$/D',$version))return null;$dir=ocs_dir().'/customer-policies';if(is_link($dir))return null;$path=$dir.'/'.$version.'.json';if(is_link($path)||!is_file($path)||filesize($path)>180000)return null;$p=json_decode((string)file_get_contents($path),true);if(!is_array($p))return null;$content=['version'=>$p['version']??'','policy_text'=>$p['policy_text']??'','consent_text'=>$p['consent_text']??''];$hash=hash('sha256',json_encode($content,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR));return isset($p['hash'])&&hash_equals($p['hash'],$hash)?$p:null;}
function ocs_policy_write(array $policy):void{$dir=ocs_dir(true).'/customer-policies';ocs_need(!is_link($dir),'Небезопасный путь политики.');if(!is_dir($dir))ocs_need(mkdir($dir,0700),'Не удалось сохранить политику.');ocs_atomic($dir.'/'.$policy['version'].'.json',$policy);}
function ocs_active_policy(array $s):?array{$p=ocs_policy((string)($s['policy_version']??''));return $p&&($p['state']??'')==='APPROVED'&&($s['policy_hash']??'')===$p['hash']?$p:null;}
function ocs_runtime_overlay(array $base):array{
 try{$s=ocs_read();$p=ocs_active_policy($s);if(($s['prep_enabled']??false)===true&&$p)foreach(['crm_operations_enabled','client_collaboration_enabled','catalog_enabled','ai_pricing_enabled'] as $key)$base[$key]=true;$open=($s['portal_enabled']??$s['public_enabled']??false)===true&&$p;$base['customer_auth_enabled']=$open;$base['customer_auth_privacy_approved']=(bool)$p;$base['customer_registration_enabled']=false;$base['paid_client_invitation_required']=true;$base['customer_mail_verified']=isset($s['mail_verified_at'],$s['mail']);$base['catalog_requests_enabled']=$open;$base['catalog_privacy_approved']=(bool)$p;if(isset($s['mail'])&&is_array($s['mail']))$base['customer_mail']=$s['mail'];$base['customer_scoped_privacy_required']=true;$base['billing_email_enabled']=($s['email_notifications_enabled']??false)===true&&isset($s['mail_verified_at'])&&$p;$base['billing_owner_email']=$s['owner_notification_email']??'';$base['max_workflow_notifications_enabled']=($s['max_workflow_notifications_enabled']??false)===true&&$p&&($s['prep_enabled']??false)===true;}catch(Throwable $e){$base['billing_email_enabled']=false;$base['max_workflow_notifications_enabled']=false;$base['customer_auth_enabled']=false;$base['catalog_requests_enabled']=$open;$base['customer_scoped_privacy_required']=true;}$base['prospect_exchange_enabled']=isset($s,$p)&&$p&&($s['prep_enabled']??false)===true&&($s['document_exchange_enabled']??false)===true;$base['customer_registration_enabled']=false;$base['paid_client_invitation_required']=true;$base['billing_enabled']=false;$base['ai_enabled']=false;return $base;
}
function ca_privacy_settings():array{
 $c=config();if(($c['customer_scoped_privacy_required']??false)!==true)return privacy_settings();
 try{$s=ocs_read();$p=ocs_active_policy($s);if($p)return ['enabled'=>true,'version'=>$p['version'],'hash'=>$p['hash'],'url'=>'/customer-privacy.php?version='.$p['version'],'consent_url'=>'/customer-privacy.php?document=consent&version='.$p['version']];}catch(Throwable $e){}return ['enabled'=>false,'version'=>'','hash'=>'','url'=>'/customer-privacy.php','consent_url'=>'/customer-privacy.php?document=consent'];
}
